def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    def dominant(values):
        color, count = Counter(values).most_common(1)[0]
        return color if count >= len(values) * 0.7 else None

    rows = [(r, dominant(grid[r])) for r in range(h)]
    cols = [(c, dominant([grid[r][c] for r in range(h)])) for c in range(w)]
    rows = [(r, color) for r, color in rows if color is not None]
    cols = [(c, color) for c, color in cols if color is not None]

    def periodic(lines):
        if len(lines) < 2:
            return lines
        gaps = [lines[i + 1][0] - lines[i][0] for i in range(len(lines) - 1)]
        step = Counter(gaps).most_common(1)[0][0]
        return [x for x in lines if (x[0] - lines[0][0]) % step == 0]

    rows = periodic(rows)
    cols = periodic(cols)
    nr, nc = max(1, len(rows) - 1), max(1, len(cols) - 1)

    row_set = {r for r, _ in rows}
    col_set = {c for c, _ in cols}
    interiors = Counter(grid[r][c] for r in range(h) for c in range(w)
                        if r not in row_set and c not in col_set)
    background = interiors.most_common(1)[0][0] if interiors else 0
    out = [[background for _ in range(nc)] for _ in range(nr)]

    divider = rows[0][1] if rows else None
    for i, (r, _) in enumerate(rows[:nr]):
        for j, (c, _) in enumerate(cols[:nc]):
            value = grid[r][c]
            if value != divider:
                out[i][j] = value
    return out
